insert into exercises (id, node_id, type, position, content) values
  ('m6-e1', 'm6-rag-vectors', 'recall', 1, '{"prompt": "Calentamiento (M5): tienes que llamar a una API de embeddings 5.000 veces. ¿Qué dos primitivas de asyncio usarías y para qué sirve cada una?", "isCode": false, "modelAnswer": "gather para lanzar las llamadas concurrentemente y recoger resultados en orden, y Semaphore para limitar cuántas están en vuelo a la vez y no superar el rate limit de la API.", "meta": {"difficulty": 1, "interview": false, "concepts": ["gather", "Semaphore"], "recuerda_de": "m5-async"}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e2', 'm6-rag-vectors', 'predict_output', 2, '{"prompt": "Chunking con ventana deslizante. ¿Qué imprime? Cuenta con cuidado el solapamiento.", "code": "def chunks(tokens, tam, solape):\n    paso = tam - solape\n    return [tokens[i:i+tam] for i in range(0, len(tokens), paso)]\n\nt = list(''ABCDEFGH'')\nfor c in chunks(t, 4, 1):\n    print(''''.join(c))", "expected_output": "ABCD\nDEFG\nGH", "explanation": "Con tamaño 4 y solape 1 el paso es 3: los chunks empiezan en 0, 3 y 6. El último queda corto (GH) porque no hay más tokens. Ese chunk final corto es una decisión real: descartarlo, rellenarlo o fusionarlo con el anterior.", "meta": {"difficulty": 2, "interview": true, "concepts": ["chunking", "solapamiento"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e3', 'm6-rag-vectors', 'predict_output', 3, '{"prompt": "Similitud coseno a mano. ¿Qué imprime? Piensa en la geometría antes de calcular.", "code": "import math\n\ndef cos(a, b):\n    dot = sum(x*y for x, y in zip(a, b))\n    na = math.sqrt(sum(x*x for x in a))\n    nb = math.sqrt(sum(y*y for y in b))\n    return round(dot / (na * nb), 2)\n\nprint(cos([1, 0], [1, 0]))\nprint(cos([1, 0], [0, 1]))\nprint(cos([1, 0], [5, 0]))\nprint(cos([1, 1], [-1, -1]))", "expected_output": "1.0\n0.0\n1.0\n-1.0", "explanation": "El coseno mide el ángulo, no la longitud: [1,0] y [5,0] apuntan igual, así que dan 1.0. Vectores perpendiculares dan 0 y opuestos -1. Por eso los embeddings suelen normalizarse: solo importa la dirección.", "meta": {"difficulty": 2, "interview": true, "concepts": ["similitud coseno", "normalización"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e4', 'm6-rag-vectors', 'parsons', 4, '{"prompt": "Ordena las líneas para implementar la búsqueda top-k: dado un vector de consulta y un índice {id: vector}, devuelve los k ids más similares.", "lines": ["def top_k(consulta, indice, k, sim):", "    puntuaciones = [(sim(consulta, v), id_) for id_, v in indice.items()]", "    puntuaciones.sort(reverse=True)", "    return [id_ for _, id_ in puntuaciones[:k]]"], "meta": {"difficulty": 1, "interview": false, "concepts": ["top-k", "retrieval"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e5', 'm6-rag-vectors', 'fix_bug', 5, '{"prompt": "Esta función normaliza un vector para que tenga norma 1. Tiene dos bugs: divide por cero con el vector nulo, y no normaliza realmente (usa la suma en vez de la norma euclídea). Arréglala: para el vector nulo devuelve el mismo vector.", "starter_code": "import math\n\ndef normalizar(v):\n    n = sum(v)\n    return [x / n for x in v]", "tests": [{"call": "normalizar([3, 4])", "expected": "[0.6, 0.8]"}, {"call": "normalizar([0, 0])", "expected": "[0, 0]"}, {"call": "round(sum(x*x for x in normalizar([1, 2, 2])), 6)", "expected": "1.0"}], "hints": ["La norma euclídea es la raíz de la suma de cuadrados, no la suma de componentes.", "Comprueba si la norma es 0 antes de dividir.", "n = math.sqrt(sum(x*x for x in v)); if n == 0: return v"], "solution": "import math\n\ndef normalizar(v):\n    n = math.sqrt(sum(x*x for x in v))\n    if n == 0:\n        return v\n    return [x / n for x in v]", "meta": {"difficulty": 2, "interview": false, "concepts": ["norma", "normalización"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e6', 'm6-rag-vectors', 'code', 6, '{"prompt": "Escribe `chunk_texto(texto, tam, solape)` que parta el texto en chunks de `tam` palabras con `solape` palabras compartidas entre consecutivos, y devuelva una lista de strings. Si el último chunk queda con menos de `solape`+1 palabras nuevas... no te compliques: simplemente incluye todos los chunks generados por la ventana, pero sin producir uno que esté completamente contenido en el anterior.", "starter_code": "def chunk_texto(texto, tam, solape):\n    pass", "tests": [{"call": "chunk_texto(''a b c d e f g'', 3, 1)", "expected": "[''a b c'', ''c d e'', ''e f g'']"}, {"call": "chunk_texto(''a b c d e'', 4, 2)", "expected": "[''a b c d'', ''c d e'']"}, {"call": "chunk_texto(''a b'', 5, 1)", "expected": "[''a b'']"}], "hints": ["Separa en palabras con split() y avanza con paso = tam - solape.", "Genera ventanas palabras[i:i+tam] y detente cuando i+tam supere la longitud, salvo la primera.", "for i in range(0, len(p), paso): trozo = p[i:i+tam]; añade y si i+tam >= len(p): break"], "solution": "def chunk_texto(texto, tam, solape):\n    p = texto.split()\n    paso = tam - solape\n    out = []\n    for i in range(0, len(p), paso):\n        out.append('' ''.join(p[i:i+tam]))\n        if i + tam >= len(p):\n            break\n    return out", "meta": {"difficulty": 2, "interview": true, "concepts": ["chunking"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e7', 'm6-rag-vectors', 'code', 7, '{"prompt": "Implementa un índice de búsqueda léxica mínimo: `class IndiceLexico` con `add(id_, texto)` y `buscar(consulta, k)` que puntúe cada documento por el número de palabras de la consulta (en minúsculas) que contiene, y devuelva los k ids con más coincidencias, desempatando por id ascendente. Es la base de BM25 sin el peso IDF.", "starter_code": "class IndiceLexico:\n    def __init__(self):\n        self.docs = {}\n\n    def add(self, id_, texto):\n        pass\n\n    def buscar(self, consulta, k):\n        pass", "tests": [{"call": "ix = IndiceLexico(); ix.add(''a'', ''Apple revenue grew''); ix.add(''b'', ''Nvidia revenue and margin''); ix.add(''c'', ''weather today''); ix.buscar(''revenue margin'', 2)", "expected": "[''b'', ''a'']"}, {"call": "ix = IndiceLexico(); ix.add(''x'', ''hola mundo''); ix.buscar(''adios'', 1)", "expected": "[''x'']"}], "hints": ["Guarda cada documento como un set de palabras en minúsculas.", "La puntuación es len(palabras_consulta & palabras_doc).", "sorted(self.docs, key=lambda i: (-score(i), i))[:k]"], "solution": "class IndiceLexico:\n    def __init__(self):\n        self.docs = {}\n\n    def add(self, id_, texto):\n        self.docs[id_] = set(texto.lower().split())\n\n    def buscar(self, consulta, k):\n        q = set(consulta.lower().split())\n        score = lambda i: len(q & self.docs[i])\n        return sorted(self.docs, key=lambda i: (-score(i), i))[:k]", "meta": {"difficulty": 2, "interview": false, "concepts": ["búsqueda léxica", "BM25"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e8', 'm6-rag-vectors', 'code', 8, '{"prompt": "Implementa `rrf(listas, k=60)`: fusión de rankings por Reciprocal Rank Fusion. Recibe varias listas de ids ordenadas (p. ej. la del retriever léxico y la del vectorial) y devuelve una única lista de ids ordenada por la suma de 1/(k + posición), con posición empezando en 1. Empates: por id ascendente.", "starter_code": "def rrf(listas, k=60):\n    pass", "tests": [{"call": "rrf([[''a'', ''b'', ''c''], [''b'', ''a'', ''d'']])", "expected": "[''a'', ''b'', ''c'', ''d'']"}, {"call": "rrf([[''x''], [''y'']])", "expected": "[''x'', ''y'']"}, {"call": "rrf([[''a'', ''b''], [''c'', ''b'']])", "expected": "[''b'', ''a'', ''c'']"}], "hints": ["Acumula puntuaciones en un dict id -> float.", "Para cada lista, enumerate(lista, start=1) te da la posición.", "sorted(puntos, key=lambda i: (-puntos[i], i))"], "solution": "def rrf(listas, k=60):\n    puntos = {}\n    for lista in listas:\n        for pos, id_ in enumerate(lista, start=1):\n            puntos[id_] = puntos.get(id_, 0) + 1 / (k + pos)\n    return sorted(puntos, key=lambda i: (-puntos[i], i))", "meta": {"difficulty": 3, "interview": true, "concepts": ["RRF", "búsqueda híbrida"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e9', 'm6-rag-vectors', 'code', 9, '{"prompt": "Implementa `recall_at_k(relevantes, recuperados, k)`: qué fracción de los ids relevantes aparece entre los k primeros recuperados. Es la métrica de retrieval que se mide ANTES de tocar el LLM.", "starter_code": "def recall_at_k(relevantes, recuperados, k):\n    pass", "tests": [{"call": "recall_at_k({''a'', ''b''}, [''b'', ''x'', ''a'', ''y''], 2)", "expected": "0.5"}, {"call": "recall_at_k({''a'', ''b''}, [''b'', ''x'', ''a'', ''y''], 3)", "expected": "1.0"}, {"call": "recall_at_k(set(), [''a''], 1)", "expected": "0.0"}], "hints": ["Corta la lista a los k primeros y conviértela en set.", "Intersección con relevantes, dividido entre len(relevantes).", "Si no hay relevantes, devuelve 0.0 para evitar dividir por cero."], "solution": "def recall_at_k(relevantes, recuperados, k):\n    if not relevantes:\n        return 0.0\n    top = set(recuperados[:k])\n    return len(top & set(relevantes)) / len(relevantes)", "meta": {"difficulty": 2, "interview": true, "concepts": ["recall@k", "evaluación de retrieval"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e10', 'm6-rag-vectors', 'recall', 10, '{"prompt": "Entrevista: en rag-finance usaste embeddings con task types asimétricos (uno para documentos, otro para consultas). ¿Por qué existe esa asimetría y qué pasaría si embebieras las preguntas con el mismo modo que los documentos?", "isCode": false, "modelAnswer": "Una pregunta y el pasaje que la responde tienen forma distinta: la pregunta es corta e interrogativa, el pasaje es largo y declarativo. Los modelos asimétricos aprenden a proyectar ambos al mismo espacio para que se acerquen aunque no compartan palabras. Usar el mismo modo para ambos degrada el retrieval, sobre todo en preguntas cortas, porque el modelo las trata como si fueran documentos.", "meta": {"difficulty": 3, "interview": true, "concepts": ["embeddings asimétricos", "retrieval"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e11', 'm6-rag-vectors', 'recall', 11, '{"prompt": "Entrevista: tu evaluación con RAGAS dio faithfulness 1.0, context recall 1.0 y answer relevancy 0.85. Explica qué mide cada una y por qué la última puede ser menor aunque las otras dos sean perfectas.", "isCode": false, "modelAnswer": "Faithfulness: si la respuesta está sustentada por el contexto recuperado (no alucina). Context recall: si el contexto recuperado contiene lo necesario para responder. Answer relevancy: si la respuesta responde exactamente a la pregunta. Puede ser menor aun con las otras perfectas si la respuesta es correcta y fundamentada pero incluye información de más, se va por las ramas o no ataca directamente la pregunta.", "meta": {"difficulty": 3, "interview": true, "concepts": ["RAGAS", "métricas"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e12', 'm6-rag-vectors', 'flashcard', 12, '{"prompt": "¿Por qué se normalizan los embeddings antes de compararlos?", "answer": "Para que el producto escalar equivalga al coseno y la comparación dependa solo de la dirección semántica, no de la magnitud.", "explanation": "Con vectores normalizados, dot(a, b) == cos(a, b), lo que además acelera la búsqueda.", "meta": {"difficulty": 1, "interview": true, "concepts": ["normalización"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e13', 'm6-rag-vectors', 'flashcard', 13, '{"prompt": "¿Qué es la búsqueda híbrida en RAG?", "answer": "Combinar retrieval léxico (BM25, coincidencia exacta de términos) con retrieval vectorial (semántico) y fusionar los rankings, típicamente con RRF.", "explanation": "El léxico acierta con nombres propios, cifras y siglas; el vectorial con paráfrasis. Juntos cubren los fallos del otro.", "meta": {"difficulty": 2, "interview": true, "concepts": ["búsqueda híbrida"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e14', 'm6-rag-vectors', 'flashcard', 14, '{"prompt": "¿Qué problema resuelve el solapamiento entre chunks?", "answer": "Que una frase o idea que cae justo en el corte entre dos chunks no quede partida y sea irrecuperable por ninguno de los dos.", "explanation": "A cambio duplica algo de contenido en el índice; 10-20% del tamaño del chunk es un valor habitual.", "meta": {"difficulty": 1, "interview": false, "concepts": ["chunking"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m6-e15', 'm6-rag-vectors', 'flashcard', 15, '{"prompt": "¿Qué es un reranker y en qué punto del pipeline actúa?", "answer": "Un modelo (cross-encoder) que recibe pregunta y pasaje juntos y devuelve una puntuación de relevancia más precisa. Actúa después del retrieval inicial, sobre los top-k, antes de pasar contexto al LLM.", "explanation": "Es más lento que un embedding, por eso solo se aplica a los pocos candidatos recuperados.", "meta": {"difficulty": 2, "interview": true, "concepts": ["reranking"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e1', 'm7-prompting-tools', 'recall', 1, '{"prompt": "Calentamiento (M6): ¿qué hace Reciprocal Rank Fusion y por qué se usa en lugar de sumar las puntuaciones brutas de dos retrievers?", "isCode": false, "modelAnswer": "Suma 1/(k + posición) de cada id en cada ranking. Se usa porque las puntuaciones de BM25 y de coseno están en escalas distintas y no son comparables; las posiciones sí lo son.", "meta": {"difficulty": 1, "interview": false, "concepts": ["RRF"], "recuerda_de": "m6-rag-vectors"}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e2', 'm7-prompting-tools', 'predict_output', 2, '{"prompt": "Plantillas de prompt. ¿Qué imprime? Atento a las llaves dobles y al método format.", "code": "plantilla = ''Responde en JSON con la clave {{\"respuesta\"}}. Pregunta: {pregunta}''\nprint(plantilla.format(pregunta=''¿capital de Francia?''))\n\nsistema = \"Eres un analista. Contexto:\\n{ctx}\\n---\"\nprint(sistema.format(ctx=''\\n''.join([''[1] doc a'', ''[2] doc b''])))", "expected_output": "Responde en JSON con la clave {\"respuesta\"}. Pregunta: ¿capital de Francia?\nEres un analista. Contexto:\n[1] doc a\n[2] doc b\n---", "explanation": "En format(), las llaves dobles {{ }} producen llaves literales: imprescindible cuando el prompt contiene ejemplos JSON. El contexto se inyecta con identificadores [1], [2] para que el modelo pueda citar.", "meta": {"difficulty": 2, "interview": false, "concepts": ["plantillas", "format", "llaves escapadas"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e3', 'm7-prompting-tools', 'predict_output', 3, '{"prompt": "Parseo de una llamada a herramienta. ¿Qué imprime?", "code": "import json\n\nrespuesta = ''{\"tool\": \"buscar\", \"args\": {\"q\": \"nvidia margin\", \"k\": 3}}''\nllamada = json.loads(respuesta)\nprint(llamada[''tool''])\nprint(sorted(llamada[''args''].items()))\nprint(type(llamada[''args''][''k'']).__name__)", "expected_output": "buscar\n[(''k'', 3), (''q'', ''nvidia margin'')]\nint", "explanation": "json.loads convierte el texto en dict y respeta los tipos JSON: 3 llega como int, no como str. Ese es el motivo de pedir salida JSON al modelo en vez de texto libre: los argumentos ya vienen tipados.", "meta": {"difficulty": 1, "interview": false, "concepts": ["json.loads", "tool calling"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e4', 'm7-prompting-tools', 'parsons', 4, '{"prompt": "Ordena las líneas para construir un dispatcher: dado el nombre de la herramienta y sus argumentos, ejecuta la función registrada o lanza un error claro.", "lines": ["HERRAMIENTAS = {}", "", "def registrar(fn):", "    HERRAMIENTAS[fn.__name__] = fn", "    return fn", "", "def ejecutar(llamada):", "    fn = HERRAMIENTAS.get(llamada[''tool''])", "    if fn is None:", "        raise KeyError(f\"herramienta desconocida: {llamada[''tool'']}\")", "    return fn(**llamada[''args''])"], "meta": {"difficulty": 2, "interview": true, "concepts": ["dispatcher", "registro de herramientas"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e5', 'm7-prompting-tools', 'fix_bug', 5, '{"prompt": "Los modelos a veces devuelven el JSON envuelto en un bloque de código markdown (```json ... ```) y con texto alrededor. Esta función falla en ese caso. Arréglala para que extraiga el primer objeto JSON válido entre la primera ''{'' y la última ''}''.", "starter_code": "import json\n\ndef extraer_json(texto):\n    return json.loads(texto)", "tests": [{"call": "extraer_json(''{\"a\": 1}'')", "expected": "{''a'': 1}"}, {"call": "extraer_json(''Claro, aquí tienes:\\n```json\\n{\"a\": 1, \"b\": [2]}\\n```'')", "expected": "{''a'': 1, ''b'': [2]}"}, {"call": "extraer_json(''resultado: {\"ok\": true} fin'')", "expected": "{''ok'': True}"}], "hints": ["Localiza la primera llave de apertura con find(''{'') y la última de cierre con rfind(''}'').", "Recorta el texto a ese rango (inclusive) antes de json.loads.", "return json.loads(texto[texto.find(''{''): texto.rfind(''}'') + 1])"], "solution": "import json\n\ndef extraer_json(texto):\n    ini = texto.find(''{'')\n    fin = texto.rfind(''}'')\n    return json.loads(texto[ini:fin + 1])", "meta": {"difficulty": 2, "interview": true, "concepts": ["salida estructurada", "parseo robusto"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e6', 'm7-prompting-tools', 'code', 6, '{"prompt": "Escribe `esquema(fn)` que genere la descripción JSON de una herramienta a partir de una función Python: nombre, descripción (su docstring) y parámetros con tipo, usando las anotaciones. Mapea int→''integer'', str→''string'', float→''number'', bool→''boolean''. Es lo que el SDK hace por ti; hacerlo a mano te enseña qué ve el modelo.", "starter_code": "def esquema(fn):\n    pass\n\ndef buscar(q: str, k: int) -> list:\n    \"\"\"Busca documentos.\"\"\"\n    return []", "tests": [{"call": "esquema(buscar)", "expected": "{''name'': ''buscar'', ''description'': ''Busca documentos.'', ''parameters'': {''q'': ''string'', ''k'': ''integer''}}"}], "hints": ["fn.__name__, fn.__doc__ y fn.__annotations__ tienen todo lo que necesitas.", "__annotations__ incluye ''return'': exclúyelo.", "tipos = {int: ''integer'', str: ''string'', float: ''number'', bool: ''boolean''}"], "solution": "def esquema(fn):\n    tipos = {int: ''integer'', str: ''string'', float: ''number'', bool: ''boolean''}\n    params = {n: tipos[t] for n, t in fn.__annotations__.items() if n != ''return''}\n    return {''name'': fn.__name__, ''description'': fn.__doc__, ''parameters'': params}\n\ndef buscar(q: str, k: int) -> list:\n    \"\"\"Busca documentos.\"\"\"\n    return []", "meta": {"difficulty": 3, "interview": true, "concepts": ["esquema de herramienta", "introspección"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e7', 'm7-prompting-tools', 'code', 7, '{"prompt": "Escribe `validar(salida, campos)`: recibe un dict parseado del modelo y un dict {campo: tipo}; devuelve una lista de errores en texto (vacía si todo está bien). Errores: ''falta <campo>'' y ''<campo> debería ser <tipo>''. Es el paso previo a reintentar con el error como feedback.", "starter_code": "def validar(salida, campos):\n    pass", "tests": [{"call": "validar({''ticker'': ''NVDA'', ''score'': 0.8}, {''ticker'': str, ''score'': float})", "expected": "[]"}, {"call": "validar({''ticker'': ''NVDA''}, {''ticker'': str, ''score'': float})", "expected": "[''falta score'']"}, {"call": "validar({''ticker'': 7, ''score'': ''alto''}, {''ticker'': str, ''score'': float})", "expected": "[''ticker debería ser str'', ''score debería ser float'']"}], "hints": ["Recorre campos.items() en orden y acumula mensajes.", "Comprueba primero presencia con ''in'', luego tipo con isinstance.", "tipo.__name__ te da ''str'', ''float''."], "solution": "def validar(salida, campos):\n    errores = []\n    for campo, tipo in campos.items():\n        if campo not in salida:\n            errores.append(f''falta {campo}'')\n        elif not isinstance(salida[campo], tipo):\n            errores.append(f''{campo} debería ser {tipo.__name__}'')\n    return errores", "meta": {"difficulty": 2, "interview": true, "concepts": ["validación de salida", "structured output"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e8', 'm7-prompting-tools', 'code', 8, '{"prompt": "Implementa el bucle de reintento: `con_reintentos(llamar, validar, intentos)`. `llamar(feedback)` simula al modelo y devuelve un dict; `validar(dict)` devuelve lista de errores. Llama con feedback=None la primera vez; si hay errores, vuelve a llamar pasando los errores unidos por ''; ''. Devuelve el primer dict válido, o None tras agotar intentos.", "starter_code": "def con_reintentos(llamar, validar, intentos):\n    pass\n\n# simulador: acierta solo cuando recibe feedback\ndef modelo(feedback):\n    return {''score'': 1.0} if feedback else {''score'': ''alto''}\n\ndef val(d):\n    return [] if isinstance(d[''score''], float) else [''score debería ser float'']", "tests": [{"call": "con_reintentos(modelo, val, 3)", "expected": "{''score'': 1.0}"}, {"call": "con_reintentos(modelo, val, 1)", "expected": "None"}, {"call": "con_reintentos(lambda f: {''score'': 2.0}, val, 1)", "expected": "{''score'': 2.0}"}], "hints": ["Un bucle for _ in range(intentos) con una variable feedback que empieza en None.", "Si validar devuelve lista vacía, devuelve el resultado; si no, actualiza feedback.", "feedback = ''; ''.join(errores)"], "solution": "def con_reintentos(llamar, validar, intentos):\n    feedback = None\n    for _ in range(intentos):\n        r = llamar(feedback)\n        errores = validar(r)\n        if not errores:\n            return r\n        feedback = ''; ''.join(errores)\n    return None\n\n# simulador: acierta solo cuando recibe feedback\ndef modelo(feedback):\n    return {''score'': 1.0} if feedback else {''score'': ''alto''}\n\ndef val(d):\n    return [] if isinstance(d[''score''], float) else [''score debería ser float'']", "meta": {"difficulty": 3, "interview": true, "concepts": ["reintentos con feedback", "self-correction"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e9', 'm7-prompting-tools', 'match', 9, '{"prompt": "Une cada técnica de prompting con la situación en la que aporta más.", "pairs": [{"term": "Few-shot", "definition": "Quieres un formato o estilo muy concreto y es más fácil mostrarlo que describirlo"}, {"term": "Chain-of-thought", "definition": "La tarea requiere varios pasos de razonamiento y el modelo falla al saltar directamente a la respuesta"}, {"term": "System prompt con rol", "definition": "Necesitas fijar tono, límites y comportamiento estable a lo largo de toda la conversación"}, {"term": "Salida estructurada (JSON schema)", "definition": "El resultado lo va a consumir código, no una persona"}, {"term": "Tool calling", "definition": "El modelo necesita datos o acciones que no tiene: buscar, calcular, consultar una API"}], "meta": {"difficulty": 2, "interview": true, "concepts": ["técnicas de prompting"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e10', 'm7-prompting-tools', 'recall', 10, '{"prompt": "Entrevista: ¿qué diferencia hay entre pedirle al modelo ''responde en JSON'' en el prompt y usar el modo de salida estructurada / tool calling del API? ¿Cuándo basta lo primero?", "isCode": false, "modelAnswer": "Pedirlo en el prompt es una sugerencia: el modelo suele cumplir pero puede añadir texto, envolverlo en markdown o romper el esquema, así que hay que parsear defensivamente y reintentar. La salida estructurada del API restringe la generación al esquema y garantiza JSON válido. Lo primero basta en prototipos o cuando el coste de un fallo es bajo; en producción, con código consumiendo la salida, conviene lo segundo.", "meta": {"difficulty": 2, "interview": true, "concepts": ["structured output"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e11', 'm7-prompting-tools', 'recall', 11, '{"prompt": "Entrevista: en trade-signal-agent usaste function calling de Gemini para razonamiento multi-paso. Describe el ciclo completo de una llamada a herramienta: quién decide, quién ejecuta y qué vuelve al modelo.", "isCode": false, "modelAnswer": "El modelo recibe los esquemas de las herramientas y decide si necesita una, devolviendo nombre y argumentos en vez de texto. Mi código (no el modelo) ejecuta la función real con esos argumentos y devuelve el resultado al modelo como un mensaje de tipo tool result. El modelo lo lee y decide: otra llamada o respuesta final. El bucle lo controla mi código, con un máximo de pasos.", "meta": {"difficulty": 3, "interview": true, "concepts": ["ciclo de tool calling", "agente"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e12', 'm7-prompting-tools', 'flashcard', 12, '{"prompt": "¿Qué es la temperatura en un LLM y qué valor usarías para extracción de datos?", "answer": "Controla la aleatoriedad del muestreo de tokens. Para extracción o clasificación, 0 (o muy baja): quieres la salida más probable y reproducible.", "explanation": "Temperaturas altas son para creatividad; para tool calling y JSON siempre baja.", "meta": {"difficulty": 1, "interview": true, "concepts": ["temperatura"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e13', 'm7-prompting-tools', 'flashcard', 13, '{"prompt": "¿Qué es prompt injection?", "answer": "Que texto no confiable (un documento, una web, un usuario) contenga instrucciones que el modelo obedezca como si vinieran del desarrollador.", "explanation": "En RAG es crítico: el contexto recuperado es datos, no instrucciones, y el prompt debe dejarlo claro.", "meta": {"difficulty": 2, "interview": true, "concepts": ["seguridad"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m7-e14', 'm7-prompting-tools', 'flashcard', 14, '{"prompt": "¿Por qué se numeran o etiquetan los pasajes de contexto en un prompt de RAG?", "answer": "Para que el modelo pueda citar la fuente de cada afirmación ([1], [2]) y para poder verificar faithfulness después.", "explanation": "Sin identificadores no hay trazabilidad de qué chunk sustentó qué frase.", "meta": {"difficulty": 1, "interview": false, "concepts": ["citas en RAG"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e1', 'm8-agents-langgraph', 'recall', 1, '{"prompt": "Calentamiento (M7): ¿por qué el bucle de un agente con herramientas debe tener un número máximo de pasos?", "isCode": false, "modelAnswer": "Porque el modelo puede entrar en un ciclo (llamar a la misma herramienta una y otra vez, o no converger a una respuesta), y sin tope el coste y la latencia se disparan. El límite convierte un posible bucle infinito en un fallo controlado.", "meta": {"difficulty": 1, "interview": true, "concepts": ["max_steps"], "recuerda_de": "m7-prompting-tools"}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e2', 'm8-agents-langgraph', 'predict_output', 2, '{"prompt": "Estado de un grafo con reducer. ¿Qué imprime? Fíjate en qué campos se sobreescriben y cuáles se acumulan.", "code": "def aplicar(estado, cambio, reducers):\n    nuevo = dict(estado)\n    for k, v in cambio.items():\n        if k in reducers:\n            nuevo[k] = reducers[k](nuevo.get(k), v)\n        else:\n            nuevo[k] = v\n    return nuevo\n\nreducers = {''mensajes'': lambda viejo, nuevo: (viejo or []) + nuevo}\ns = {''paso'': 0, ''mensajes'': [''hola'']}\ns = aplicar(s, {''paso'': 1, ''mensajes'': [''busco'']}, reducers)\ns = aplicar(s, {''paso'': 2, ''mensajes'': [''listo'']}, reducers)\nprint(s[''paso''], s[''mensajes''])", "expected_output": "2 [''hola'', ''busco'', ''listo'']", "explanation": "Un reducer define cómo se combina un campo del estado: ''mensajes'' acumula (como add_messages en LangGraph), mientras ''paso'' sin reducer simplemente se sustituye. Es la diferencia entre historial y estado actual.", "meta": {"difficulty": 2, "interview": true, "concepts": ["reducers", "estado del grafo"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e3', 'm8-agents-langgraph', 'parsons', 3, '{"prompt": "Ordena las líneas para definir la estructura mínima de un grafo: nodos (funciones que reciben estado y devuelven cambios) y aristas (de qué nodo a cuál).", "lines": ["class Grafo:", "    def __init__(self):", "        self.nodos = {}", "        self.aristas = {}", "", "    def add_node(self, nombre, fn):", "        self.nodos[nombre] = fn", "", "    def add_edge(self, origen, destino):", "        self.aristas[origen] = destino"], "meta": {"difficulty": 1, "interview": false, "concepts": ["grafo", "nodos y aristas"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e4', 'm8-agents-langgraph', 'code', 4, '{"prompt": "Paso 1 del mini-LangGraph. Completa `run(self, estado, inicio)`: empieza en el nodo `inicio`, ejecuta su función (que devuelve un dict de cambios), actualiza el estado con `update`, y sigue la arista hasta llegar a ''END''. Devuelve el estado final.", "starter_code": "class Grafo:\n    def __init__(self):\n        self.nodos = {}\n        self.aristas = {}\n\n    def add_node(self, nombre, fn):\n        self.nodos[nombre] = fn\n\n    def add_edge(self, origen, destino):\n        self.aristas[origen] = destino\n\n    def run(self, estado, inicio):\n        pass\n\ng = Grafo()\ng.add_node(''a'', lambda s: {''x'': s[''x''] + 1})\ng.add_node(''b'', lambda s: {''x'': s[''x''] * 10})\ng.add_edge(''a'', ''b'')\ng.add_edge(''b'', ''END'')", "tests": [{"call": "g.run({''x'': 1}, ''a'')", "expected": "{''x'': 20}"}, {"call": "g.run({''x'': 0}, ''b'')", "expected": "{''x'': 0}"}], "hints": ["Un bucle while actual != ''END''.", "cambio = self.nodos[actual](estado); estado = {**estado, **cambio}", "actual = self.aristas[actual]"], "solution": "class Grafo:\n    def __init__(self):\n        self.nodos = {}\n        self.aristas = {}\n\n    def add_node(self, nombre, fn):\n        self.nodos[nombre] = fn\n\n    def add_edge(self, origen, destino):\n        self.aristas[origen] = destino\n\n    def run(self, estado, inicio):\n        actual = inicio\n        while actual != ''END'':\n            cambio = self.nodos[actual](estado)\n            estado = {**estado, **cambio}\n            actual = self.aristas[actual]\n        return estado\n\ng = Grafo()\ng.add_node(''a'', lambda s: {''x'': s[''x''] + 1})\ng.add_node(''b'', lambda s: {''x'': s[''x''] * 10})\ng.add_edge(''a'', ''b'')\ng.add_edge(''b'', ''END'')", "meta": {"difficulty": 2, "interview": true, "concepts": ["ejecución de grafo", "estado"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e5', 'm8-agents-langgraph', 'code', 5, '{"prompt": "Paso 2: aristas condicionales. Añade `add_conditional_edge(origen, decidir)` donde `decidir(estado)` devuelve el nombre del siguiente nodo, y adapta `run` para que, si el nodo actual tiene arista condicional, la use. Ahora puedes hacer bucles: un agente que sigue llamando a herramientas hasta que decide parar.", "starter_code": "class Grafo:\n    def __init__(self):\n        self.nodos = {}\n        self.aristas = {}\n        self.condicionales = {}\n\n    def add_node(self, nombre, fn):\n        self.nodos[nombre] = fn\n\n    def add_edge(self, origen, destino):\n        self.aristas[origen] = destino\n\n    def add_conditional_edge(self, origen, decidir):\n        pass\n\n    def run(self, estado, inicio):\n        actual = inicio\n        while actual != ''END'':\n            cambio = self.nodos[actual](estado)\n            estado = {**estado, **cambio}\n            actual = self.aristas[actual]\n        return estado\n\ng = Grafo()\ng.add_node(''contar'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''contar'', lambda s: ''END'' if s[''n''] >= 3 else ''contar'')", "tests": [{"call": "g.run({''n'': 0}, ''contar'')", "expected": "{''n'': 3}"}, {"call": "g.run({''n'': 5}, ''contar'')", "expected": "{''n'': 6}"}], "hints": ["Guarda la función de decisión en self.condicionales[origen].", "En run, tras actualizar el estado, comprueba primero si actual está en condicionales.", "actual = self.condicionales[actual](estado) if actual in self.condicionales else self.aristas[actual]"], "solution": "class Grafo:\n    def __init__(self):\n        self.nodos = {}\n        self.aristas = {}\n        self.condicionales = {}\n\n    def add_node(self, nombre, fn):\n        self.nodos[nombre] = fn\n\n    def add_edge(self, origen, destino):\n        self.aristas[origen] = destino\n\n    def add_conditional_edge(self, origen, decidir):\n        self.condicionales[origen] = decidir\n\n    def run(self, estado, inicio):\n        actual = inicio\n        while actual != ''END'':\n            cambio = self.nodos[actual](estado)\n            estado = {**estado, **cambio}\n            if actual in self.condicionales:\n                actual = self.condicionales[actual](estado)\n            else:\n                actual = self.aristas[actual]\n        return estado\n\ng = Grafo()\ng.add_node(''contar'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''contar'', lambda s: ''END'' if s[''n''] >= 3 else ''contar'')", "meta": {"difficulty": 3, "interview": true, "concepts": ["aristas condicionales", "bucles"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e6', 'm8-agents-langgraph', 'code', 6, '{"prompt": "Paso 3: seguridad. Añade a `run` un parámetro `max_steps=10`: si se ejecutan más nodos que ese número, lanza RuntimeError(''max_steps''). Además registra en `estado[''traza'']` la lista de nodos visitados (crea la lista si no existe). No toques el bloque marcado.", "starter_code": "class Grafo:\n    def __init__(self):\n        self.nodos = {}\n        self.aristas = {}\n        self.condicionales = {}\n\n    def add_node(self, nombre, fn):\n        self.nodos[nombre] = fn\n\n    def add_edge(self, origen, destino):\n        self.aristas[origen] = destino\n\n    def add_conditional_edge(self, origen, decidir):\n        self.condicionales[origen] = decidir\n\n    def run(self, estado, inicio, max_steps=10):\n        actual = inicio\n        while actual != ''END'':\n            cambio = self.nodos[actual](estado)\n            estado = {**estado, **cambio}\n            if actual in self.condicionales:\n                actual = self.condicionales[actual](estado)\n            else:\n                actual = self.aristas[actual]\n        return estado\n\n# --- no tocar ---\ng = Grafo()\ng.add_node(''loop'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''loop'', lambda s: ''END'' if s[''n''] >= 2 else ''loop'')\n\ndef infinito():\n    g2 = Grafo()\n    g2.add_node(''x'', lambda s: {})\n    g2.add_edge(''x'', ''x'')\n    try:\n        g2.run({}, ''x'', max_steps=5)\n        return ''no paró''\n    except RuntimeError as e:\n        return str(e)\n# --- fin ---", "tests": [{"call": "g.run({''n'': 0}, ''loop'')[''traza'']", "expected": "[''loop'', ''loop'']"}, {"call": "infinito()", "expected": "max_steps"}], "hints": ["Lleva un contador de pasos; incrementa antes de ejecutar cada nodo.", "if pasos > max_steps: raise RuntimeError(''max_steps'')", "estado = {**estado, **cambio, ''traza'': estado.get(''traza'', []) + [actual]}"], "solution": "class Grafo:\n    def __init__(self):\n        self.nodos = {}\n        self.aristas = {}\n        self.condicionales = {}\n\n    def add_node(self, nombre, fn):\n        self.nodos[nombre] = fn\n\n    def add_edge(self, origen, destino):\n        self.aristas[origen] = destino\n\n    def add_conditional_edge(self, origen, decidir):\n        self.condicionales[origen] = decidir\n\n    def run(self, estado, inicio, max_steps=10):\n        actual = inicio\n        pasos = 0\n        while actual != ''END'':\n            pasos += 1\n            if pasos > max_steps:\n                raise RuntimeError(''max_steps'')\n            cambio = self.nodos[actual](estado)\n            estado = {**estado, **cambio, ''traza'': estado.get(''traza'', []) + [actual]}\n            if actual in self.condicionales:\n                actual = self.condicionales[actual](estado)\n            else:\n                actual = self.aristas[actual]\n        return estado\n\n# --- no tocar ---\ng = Grafo()\ng.add_node(''loop'', lambda s: {''n'': s[''n''] + 1})\ng.add_conditional_edge(''loop'', lambda s: ''END'' if s[''n''] >= 2 else ''loop'')\n\ndef infinito():\n    g2 = Grafo()\n    g2.add_node(''x'', lambda s: {})\n    g2.add_edge(''x'', ''x'')\n    try:\n        g2.run({}, ''x'', max_steps=5)\n        return ''no paró''\n    except RuntimeError as e:\n        return str(e)\n# --- fin ---", "meta": {"difficulty": 3, "interview": true, "concepts": ["max_steps", "trazabilidad"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e7', 'm8-agents-langgraph', 'code', 7, '{"prompt": "Paso 4: un agente ReAct simulado sobre tu Grafo. Te doy un ''modelo'' determinista: `pensar(s)` devuelve {''accion'': ''buscar''} si no hay resultado aún, o {''accion'': ''responder''} si ya lo hay. Escribe `construir_agente()` que cree el grafo con nodos ''pensar'', ''buscar'' (pone s[''resultado''] = ''dato'') y ''responder'' (pone s[''respuesta''] = ''Respuesta: '' + s[''resultado'']), con la arista condicional desde ''pensar'' según s[''accion''], ''buscar'' vuelve a ''pensar'' y ''responder'' va a ''END''. No toques el bloque marcado.", "starter_code": "# --- no tocar ---\nclass Grafo:\n    def __init__(self):\n        self.nodos, self.aristas, self.condicionales = {}, {}, {}\n    def add_node(self, n, fn): self.nodos[n] = fn\n    def add_edge(self, o, d): self.aristas[o] = d\n    def add_conditional_edge(self, o, f): self.condicionales[o] = f\n    def run(self, estado, inicio, max_steps=10):\n        actual, pasos = inicio, 0\n        while actual != ''END'':\n            pasos += 1\n            if pasos > max_steps: raise RuntimeError(''max_steps'')\n            estado = {**estado, **self.nodos[actual](estado), ''traza'': estado.get(''traza'', []) + [actual]}\n            actual = self.condicionales[actual](estado) if actual in self.condicionales else self.aristas[actual]\n        return estado\n\ndef pensar(s):\n    return {''accion'': ''responder'' if ''resultado'' in s else ''buscar''}\n# --- fin ---\n\ndef construir_agente():\n    pass", "tests": [{"call": "r = construir_agente().run({}, ''pensar''); r[''respuesta'']", "expected": "Respuesta: dato"}, {"call": "construir_agente().run({}, ''pensar'')[''traza'']", "expected": "[''pensar'', ''buscar'', ''pensar'', ''responder'']"}], "hints": ["Tres nodos: pensar (dado), buscar y responder como lambdas que devuelven el cambio de estado.", "La condicional desde pensar devuelve s[''accion''] tal cual: es el nombre del siguiente nodo.", "g.add_edge(''buscar'', ''pensar''); g.add_edge(''responder'', ''END'')"], "solution": "# --- no tocar ---\nclass Grafo:\n    def __init__(self):\n        self.nodos, self.aristas, self.condicionales = {}, {}, {}\n    def add_node(self, n, fn): self.nodos[n] = fn\n    def add_edge(self, o, d): self.aristas[o] = d\n    def add_conditional_edge(self, o, f): self.condicionales[o] = f\n    def run(self, estado, inicio, max_steps=10):\n        actual, pasos = inicio, 0\n        while actual != ''END'':\n            pasos += 1\n            if pasos > max_steps: raise RuntimeError(''max_steps'')\n            estado = {**estado, **self.nodos[actual](estado), ''traza'': estado.get(''traza'', []) + [actual]}\n            actual = self.condicionales[actual](estado) if actual in self.condicionales else self.aristas[actual]\n        return estado\n\ndef pensar(s):\n    return {''accion'': ''responder'' if ''resultado'' in s else ''buscar''}\n# --- fin ---\n\ndef construir_agente():\n    g = Grafo()\n    g.add_node(''pensar'', pensar)\n    g.add_node(''buscar'', lambda s: {''resultado'': ''dato''})\n    g.add_node(''responder'', lambda s: {''respuesta'': ''Respuesta: '' + s[''resultado'']})\n    g.add_conditional_edge(''pensar'', lambda s: s[''accion''])\n    g.add_edge(''buscar'', ''pensar'')\n    g.add_edge(''responder'', ''END'')\n    return g", "meta": {"difficulty": 3, "interview": true, "concepts": ["ReAct", "agente sobre grafo"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e8', 'm8-agents-langgraph', 'match', 8, '{"prompt": "Une lo que construiste a mano con su equivalente en la API real de LangGraph.", "pairs": [{"term": "Grafo()", "definition": "StateGraph(EstadoTipado)"}, {"term": "add_conditional_edge(origen, decidir)", "definition": "add_conditional_edges(origen, decidir)"}, {"term": "''END'' como destino", "definition": "La constante END importada de langgraph.graph"}, {"term": "reducer que concatena mensajes", "definition": "Annotated[list, add_messages] en el TypedDict del estado"}, {"term": "max_steps", "definition": "recursion_limit en la configuración de invoke"}, {"term": "estado[''traza'']", "definition": "Un checkpointer (MemorySaver) que persiste cada paso"}], "meta": {"difficulty": 2, "interview": true, "concepts": ["API de LangGraph"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e9', 'm8-agents-langgraph', 'recall', 9, '{"prompt": "Entrevista: ¿por qué modelar un agente como grafo de estados en lugar de un simple bucle while con if/else? Da dos ventajas concretas.", "isCode": false, "modelAnswer": "1) Cada nodo es una función pura sobre el estado: testeable por separado y reutilizable. 2) El flujo es explícito e inspeccionable: puedes dibujarlo, hacer checkpoint tras cada nodo, reanudar, o insertar un paso de aprobación humana entre dos nodos sin reescribir la lógica. Un while con ifs mezcla control de flujo y lógica de negocio y no se puede pausar ni auditar.", "meta": {"difficulty": 3, "interview": true, "concepts": ["grafo vs bucle"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e10', 'm8-agents-langgraph', 'recall', 10, '{"prompt": "Entrevista: en trade-signal-agent el backtest no mostró ventaja frente a un baseline aleatorio (4.77% vs 5.15%). ¿Por qué documentaste ese resultado en vez de ocultarlo, y qué dice eso de cómo evalúas un agente?", "isCode": false, "modelAnswer": "Porque el valor del proyecto es la metodología, no el número: comparar contra un baseline con las mismas reglas es lo que convierte una demo en una evaluación. Un resultado negativo honesto demuestra que la evaluación no está amañada y que sé distinguir ''el agente funciona'' de ''el agente produce salidas plausibles''. Ocultarlo sería exactamente el error que un empleador quiere evitar.", "meta": {"difficulty": 3, "interview": true, "concepts": ["evaluación de agentes", "baseline"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e11', 'm8-agents-langgraph', 'flashcard', 11, '{"prompt": "¿Qué es el patrón ReAct?", "answer": "Reason + Act: el modelo alterna razonar sobre el estado, elegir una acción (herramienta), observar el resultado, y repetir hasta poder responder.", "explanation": "Es el bucle pensar → herramienta → observación que implementaste sobre el grafo.", "meta": {"difficulty": 1, "interview": true, "concepts": ["ReAct"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e12', 'm8-agents-langgraph', 'flashcard', 12, '{"prompt": "¿Qué es un checkpointer en LangGraph y para qué sirve?", "answer": "Un almacén que guarda el estado del grafo tras cada paso, identificado por un thread_id. Permite reanudar, hacer time-travel, y pausar para intervención humana.", "explanation": "Sin él, cada invoke empieza de cero y no hay memoria entre turnos.", "meta": {"difficulty": 2, "interview": true, "concepts": ["checkpointer"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m8-e13', 'm8-agents-langgraph', 'flashcard', 13, '{"prompt": "¿Qué es human-in-the-loop en un agente?", "answer": "Interrumpir el grafo antes de una acción sensible (enviar, comprar, borrar) para que una persona apruebe o edite, y reanudar desde el checkpoint.", "explanation": "En un agente de trading, es la diferencia entre sugerir una operación y ejecutarla.", "meta": {"difficulty": 2, "interview": true, "concepts": ["human-in-the-loop"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e1', 'm9-capstone', 'parsons', 1, '{"prompt": "Ordena las fases de un pipeline RAG de principio a fin, tal como lo construirías de verdad (cada línea es una fase; el orden importa).", "lines": ["# 1. Ingestión: cargar y limpiar los documentos fuente", "# 2. Chunking: partir en fragmentos con solape y metadatos", "# 3. Embeddings: vectorizar cada chunk (modo documento)", "# 4. Indexación: guardar vectores + texto + metadatos en la vector DB", "# 5. Consulta: embeber la pregunta (modo consulta) y recuperar top-k", "# 6. Generación: construir el prompt con contexto citado y llamar al LLM", "# 7. Evaluación: medir faithfulness, recall y relevancy sobre un dataset fijo"], "meta": {"difficulty": 1, "interview": true, "concepts": ["pipeline RAG"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e2', 'm9-capstone', 'match', 2, '{"prompt": "Une cada componente del proyecto integrador con su responsabilidad. Cada pieza hace una sola cosa.", "pairs": [{"term": "ingest.py", "definition": "Convierte fuentes crudas en chunks con metadatos y los indexa"}, {"term": "retrieve.py", "definition": "Dada una pregunta, devuelve los k pasajes más relevantes (híbrido + rerank)"}, {"term": "generate.py", "definition": "Construye el prompt con contexto citado y llama al LLM"}, {"term": "agent.py", "definition": "Orquesta herramientas y decide cuándo buscar, calcular o responder"}, {"term": "eval.py", "definition": "Corre el dataset de evaluación y reporta métricas comparables entre versiones"}, {"term": "api.py (FastAPI)", "definition": "Expone el sistema con auth, rate limit y logging estructurado"}], "meta": {"difficulty": 2, "interview": true, "concepts": ["arquitectura", "separación de responsabilidades"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e3', 'm9-capstone', 'recall', 3, '{"prompt": "Revisión de diseño 1: tu sistema devuelve respuestas correctas pero lentas (8 s). Enumera, en orden de lo que probarías primero, tres causas probables y cómo medirías cada una.", "isCode": false, "modelAnswer": "1) Retrieval: ¿cuánto tarda la búsqueda? Medir con timestamps por fase. 2) Tamaño del prompt: demasiados chunks o chunks muy largos alargan la generación; medir tokens de entrada. 3) Llamadas secuenciales que podrían ser concurrentes (embeddings, reranker) o cold start del servidor. Primero se mide por fase; sin eso, cualquier optimización es a ciegas.", "meta": {"difficulty": 3, "interview": true, "concepts": ["rendimiento", "observabilidad"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e4', 'm9-capstone', 'recall', 4, '{"prompt": "Revisión de diseño 2: un usuario pregunta algo que no está en los documentos. ¿Qué debe hacer el sistema y en qué parte del pipeline lo implementarías?", "isCode": false, "modelAnswer": "Debe decir que no tiene información, no inventar. Dos capas: en retrieval, un umbral de similitud mínimo (si ningún chunk lo supera, no hay contexto); y en generación, una instrucción explícita de responder solo con el contexto y declarar cuándo no basta. Se verifica con casos negativos en el dataset de evaluación.", "meta": {"difficulty": 3, "interview": true, "concepts": ["abstención", "alucinaciones"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e5', 'm9-capstone', 'recall', 5, '{"prompt": "Revisión de diseño 3: cambias el modelo de embeddings por uno nuevo. ¿Qué tienes que rehacer, qué puede romperse silenciosamente, y cómo lo detectarías?", "isCode": false, "modelAnswer": "Hay que re-embeber y reindexar todos los chunks: los vectores de dos modelos no viven en el mismo espacio, así que mezclarlos rompe el retrieval sin dar error. Además puede cambiar la dimensión del vector. Se detecta corriendo eval.py antes y después: si context recall cae, algo se mezcló o el modelo es peor para el dominio.", "meta": {"difficulty": 3, "interview": true, "concepts": ["migración de embeddings", "evaluación como red de seguridad"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e6', 'm9-capstone', 'recall', 6, '{"prompt": "Revisión de diseño 4 (el pitch): tienes 60 segundos en una entrevista para explicar el proyecto integrador. Escríbelo: problema, arquitectura en una frase, la decisión técnica más interesante y el resultado medido.", "isCode": false, "modelAnswer": "Ejemplo de estructura: ''Es un asistente de análisis financiero sobre informes 10-K. Pipeline RAG híbrido con reranking, un agente que decide cuándo buscar o calcular, y una API FastAPI desplegada. La decisión más interesante fue evaluar contra un baseline y publicar que la primera versión no lo superaba; eso me llevó a cambiar el chunking y subir el context recall de 0.7 a 1.0. Todo está medido y reproducible en el repo.''", "meta": {"difficulty": 3, "interview": true, "concepts": ["comunicación técnica", "pitch"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e7', 'm9-capstone', 'flashcard', 7, '{"prompt": "¿Qué debe contener el README de un proyecto de IA para que un entrevistador lo tome en serio?", "answer": "Problema, arquitectura con diagrama, decisiones técnicas y por qué, resultados de evaluación con números, cómo reproducirlos, y limitaciones conocidas.", "explanation": "Las limitaciones y los números son lo que distingue un proyecto de portfolio de un tutorial copiado.", "meta": {"difficulty": 1, "interview": true, "concepts": ["README"]}}'::jsonb)
insert into exercises (id, node_id, type, position, content) values
  ('m9-e8', 'm9-capstone', 'flashcard', 8, '{"prompt": "¿Por qué un dataset de evaluación fijo y versionado es imprescindible?", "answer": "Porque sin él no puedes saber si un cambio (prompt, chunking, modelo) mejoró o empeoró el sistema: los números solo son comparables sobre los mismos casos.", "explanation": "Es el equivalente a la suite de tests en software clásico.", "meta": {"difficulty": 1, "interview": true, "concepts": ["dataset de evaluación"]}}'::jsonb)
